const path = require('path');
const config = require('./wdio.js').config;
const maxInstances = ('MAX_INSTANCES' in process.env && Number(process.env.MAX_INSTANCES)) || config.maxInstances;
console.log('CONFIG READ FOR CLOUD');
console.log('MAX_INSTANCES: ' + maxInstances);

config.capabilities = [
    {
        browserName: 'chrome',
        maxInstances: maxInstances,
        'goog:chromeOptions': {
            args: [
                '--no-sandbox',
                '--disable-extensions',
                '--disable-gpu',
                '--window-size=1920,1080',
                '--privileged',
                '--noopt',
                `--lang=${process.env.browserLanguage}`,
                `--accept-lang=${process.env.browserLanguage}`,
                '--disable-popup-blocking',
                '--verbose',
                '--port=9999',
                '--headless=new',
            ],
            prefs: {
                'download.default_directory': process.env.downloadFolder,
            },
        },
    },
];
//Do not add the --headless option ONLY in case HEADLESS value is set to false (to avoid affecting DevOps Env runs and legacy usage)
if ('undefined' === (typeof process.env.HEADLESS).toString()) {
    process.env.HEADLESS = 'true';
}
if (!(process.env.HEADLESS == 'true')) {
    delete process.env.HEADLESS;
    config.capabilities[0]['goog:chromeOptions']['args'].pop('--headless=new');
}

// '--proxy-server="direct://"',
config.baseUrl = process.env.CUCUMBER_BASE_URL;
config.maxInstances = maxInstances;
exports.config = config;
